        let _ = match rest.first() {
            None => writeln!(
                line,
                "p={parser:p} type={parser_type} flags={flags:02x} next=null debug={msg}"
            ),
            Some(next) => writeln!(
                line,
                "p={parser:p} type={parser_type} flags={flags:02x} next={next:02x}   debug={msg}"
