type Lenient = (fn(&mut ParserMut<'_>, bool), u32);

/// The ten lenient setters, in `llhttp_lenient_flags`' order.
const LENIENT: [Lenient; 10] = [
    (ParserMut::set_lenient_headers, sys::LENIENT_HEADERS),
    (ParserMut::set_lenient_chunked_length, sys::LENIENT_CHUNKED_LENGTH),
    (ParserMut::set_lenient_keep_alive, sys::LENIENT_KEEP_ALIVE),
    (ParserMut::set_lenient_transfer_encoding, sys::LENIENT_TRANSFER_ENCODING),
    (ParserMut::set_lenient_version, sys::LENIENT_VERSION),
    (ParserMut::set_lenient_data_after_close, sys::LENIENT_DATA_AFTER_CLOSE),
    (ParserMut::set_lenient_optional_lf_after_cr, sys::LENIENT_OPTIONAL_LF_AFTER_CR),
    (ParserMut::set_lenient_optional_crlf_after_chunk, sys::LENIENT_OPTIONAL_CRLF_AFTER_CHUNK),
    (ParserMut::set_lenient_optional_cr_before_lf, sys::LENIENT_OPTIONAL_CR_BEFORE_LF),
    (ParserMut::set_lenient_spaces_after_chunk_size, sys::LENIENT_SPACES_AFTER_CHUNK_SIZE),
];

#[test]
fn each_lenient_setter_sets_and_clears_its_own_bit() {
    for (set, bit) in LENIENT {
        let bit = u16::try_from(bit).unwrap();
        for others in [0, 0xFFFF & !bit] {
            let mut parser = Parser::zeroed();
            parser.as_mut().set_lenient_flags_raw(others);
            set(&mut parser.as_mut(), true);
            assert_eq!(parser.as_ref().lenient_flags_raw(), others | bit);
            set(&mut parser.as_mut(), true);
            assert_eq!(parser.as_ref().lenient_flags_raw(), others | bit);
            set(&mut parser.as_mut(), false);
            assert_eq!(parser.as_ref().lenient_flags_raw(), others);
            set(&mut parser.as_mut(), false);
            assert_eq!(parser.as_ref().lenient_flags_raw(), others);
        }
    }
}

#[test]
fn the_lenient_setters_together_set_every_flag() {
    let mut parser = Parser::zeroed();
    for (set, _) in LENIENT {
        set(&mut parser.as_mut(), true);
    }
    assert_eq!(parser.as_ref().lenient_flags_raw(), 0x3FF);
}

